import{_ as t,o as a,c as i,ag as s}from"./chunks/framework.CxkNbRKf.js";const n="/nada-documentation/images/image172.png",o="/nada-documentation/images/image173.png",r="/nada-documentation/images/image174.png",l="/nada-documentation/images/image175.png",d="/nada-documentation/images/image176.png",p="/nada-documentation/images/image177.png",_=JSON.parse('{"title":"Managing data requests","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/licensed-requests.md","filePath":"admin-guide/web-ui/licensed-requests.md","lastUpdated":1786379412000}'),c={name:"admin-guide/web-ui/licensed-requests.md"};function m(u,e,h,g,f,q){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="managing-data-requests" tabindex="-1">Managing data requests <a class="header-anchor" href="#managing-data-requests" aria-label="Permalink to &quot;Managing data requests&quot;">​</a></h1><p>Some datasets will be declared as being accessible only under license. This means that users need to be registered and submit a request for accessing data. Typically, this is done at the study level, and only apply to microdata and geographic datasets. Sometimes for a collection (see bulk data access).</p><h2 id="using-the-administrator-interface" tabindex="-1">Using the administrator interface <a class="header-anchor" href="#using-the-administrator-interface" aria-label="Permalink to &quot;Using the administrator interface&quot;">​</a></h2><p><img src="'+n+'" alt=""></p><p>Datasets that are assigned the Access Type Licensed require approval from a NADA administrator before the user can get access to the data files. From the site administration there are a number of ways to see if licensed requests have been received.</p><ul><li><strong>In the dashboard</strong>: Pending requests show up as red in the catalog quick summary section. Clicking on this link goes to the Licensed Survey Requests management page.</li></ul><blockquote><p><img src="'+o+'" alt=""></p></blockquote><ul><li><strong>From the Studies menu</strong>: select Licensed Requests from the submenu. The link shows a page with a list of Licensed Requests received. The status column indicates the Pending requests.</li></ul><blockquote><p><img src="'+r+'" alt=""></p></blockquote><p><img src="'+l+'" alt=""></p><p>Click on the Edit link for to process a request.</p><p>The Request information tab shows a summary of the information provided by the applicant.</p><p><img src="'+d+'" alt=""></p><p>To Approve or Deny or request further information for the request. Click on the Process tab.</p><p><img src="'+p+'" alt=""></p><ul><li><p>Select Approve to approve the request. (other options include Deny as well as Request more information from the applicant).</p></li><li><p>Select the files that the user will be authorized to download -- it is also possible to enter a maximum number of downloads and expiry date for downloads.</p></li><li><p>Enter any comments to be sent to the applicant</p></li><li><p>Select Notify user by email to notify them that the application has been processed.</p></li><li><p>Select Update.</p></li></ul><p><strong>The remaining tabs:</strong></p><ul><li><p>Communicate - provides a means to ask for more information from the applicant</p></li><li><p>Monitor -- allows the administrator to see when and how many times the applicant downloaded the data</p></li><li><p>Forward Request -- provides a means to forward the request to another person for review.</p></li></ul><h2 id="using-the-api" tabindex="-1">Using the API <a class="header-anchor" href="#using-the-api" aria-label="Permalink to &quot;Using the API&quot;">​</a></h2>',19)])])}const w=t(c,[["render",m]]);export{_ as __pageData,w as default};
